26	// The fixture recorder (DEVDESK-511, step 7). RecordFixtures replays the request
27	// of each recorded fixture against the bench and writes the redacted answer back
28	// to the same file. It sends the bench credentials, so everything that could go
29	// wrong is refused before the first fixture request, and nothing is written
30	// unless every answer passed: GET only, a closed list of paths, loopback origins
31	// only, no redirection, a leak check of what will be written.
32	
33	const (
34		// recordedBy is the value of the "recorded-by" header the recorder sets.
35		recordedBy = "nexus-bench record"
36		// recordedFileMode and recordedDirMode are the modes of a written fixture.
37		recordedFileMode os.FileMode = 0o644
38		recordedDirMode  os.FileMode = 0o755
39		// recordedDateLayout is the date of the "measured" header.
40		recordedDateLayout = "2006-01-02"
41	)
42	
43	// RecordOptions says what to record and against which bench.
44	type RecordOptions struct {
45		// Origins maps the Host of a fixture ("127.0.0.1:30481") to the base URL that
46		// reaches it. Each key must be a loopback host:port of the descriptor and each
47		// URL a loopback origin (IsLoopbackRESTHost), no user information. The REST
48		// origin (first host of the descriptor, REST node port) is required: the data
49		// set is compared through it.
50		Origins    map[string]string
51		Descriptor Descriptor
52		Secrets    Secrets
53		// Dir is the folder of the campaigns; empty means nexusfixture.SourceDir().
54		Dir string
55		// Campaigns limits the run to these campaigns; empty means every folder of Dir.
56		Campaigns []string
57		// Only is an optional glob (path.Match) on fixture names, without ".http".
58		Only string
59		// Now gives the date of the "measured" header; nil means time.Now.
60		Now func() time.Time
61		// DenyTerms are extra terms no written fixture may hold (the external deny list).
62		DenyTerms []string
63	}
64	
65	// RecordReport lists the fixtures of a run as "<campaign>/<name>". A Skipped
66	// entry is followed by ": <reason>".
67	type RecordReport struct {
68		Written, Unchanged, Skipped []string
69	}
70	
71	// recordJob is one fixture to replay.
72	type recordJob struct {
73		campaign string
74		name     string // "<campaign>/<file name without .http>"
75		path     string
76		current  nexusfixture.Fixture
77		user     string // "" for an anonymous fixture
78		password string
79		origin   string
80	}
81	
82	// recordWrite is a fixture file to replace, held back until every answer passed.
83	type recordWrite struct {
84		name string
85		path string
86		data []byte
87	}
88	
89	// RecordFixtures regenerates the recorded fixtures from the bench. A fixture is
90	// skipped (reported, never requested) when it says "record: skip" or holds more
91	// than one exchange. A fixture whose answer is the one it already holds, apart
92	// from its date, is left alone, bytes and modification time. Every error is a
93	// *BenchError, free of secrets; on an error nothing is written and the report is
94	// empty.
95	func RecordFixtures(ctx context.Context, o RecordOptions) (RecordReport, error) {
96		if err := ctx.Err(); err != nil {
97			return RecordReport{}, recordError("the recording was cancelled before it started", "run it again", err)
98		}
99		jobs, report, err := planRecording(o)
100		if err != nil {
101			return RecordReport{}, err
102		}
103		if len(jobs) > 0 {
104			if err := checkBenchDataset(ctx, o); err != nil {
105				return RecordReport{}, err
106			}
107		}
108		writes, unchanged, err := gatherAnswers(ctx, o, jobs)
109		if err != nil {
110			return RecordReport{}, err
111		}
112		report.Unchanged = unchanged
113		for i, w := range writes {
114			if err := writeFileAtomic(w.path, w.data, recordedFileMode, recordedDirMode); err != nil {
115				return RecordReport{}, recordError(
116					fmt.Sprintf("%s could not be written (%d fixture(s) of this run were already written)", w.name, i),
117					"check the permissions of the fixtures folder, then record again", err)
118			}
119			report.Written = append(report.Written, w.name)
120		}
121		return report, nil
122	}
123	
124	// recordError returns a BenchError; err is kept for errors.Is and errors.As and
125	// is never printed. A refusal with no underlying error keeps its own cause.
126	func recordError(cause, check string, err error) *BenchError {
127		if err == nil {
128			err = errors.New(cause)
129		}
130		return &BenchError{Kind: Unclassified, Cause: cause, Check: check, Err: err}
131	}
132	
133	// ---- planning: everything is checked before the first request ------------------
134	
135	// planRecording reads the fixtures and refuses anything that must not be sent.
136	func planRecording(o RecordOptions) ([]recordJob, RecordReport, error) {
137		var report RecordReport
138		if err := checkOrigins(o); err != nil {
139			return nil, report, err
140		}
141		if o.Only != "" {
142			if _, err := path.Match(o.Only, ""); err != nil {
143				return nil, report, recordError("the fixture filter is not a valid glob", "write it as a path.Match pattern, e.g. catalog-*", err)
144			}
145		}
146		dir := o.Dir
147		if dir == "" {
148			var err error
149			if dir, err = nexusfixture.SourceDir(); err != nil {
150				return nil, report, recordError("the fixtures folder of the source tree cannot be located", "run the recorder from a build that knows its source tree (not -trimpath)", err)
151			}
152		}
153		if info, err := os.Stat(dir); err != nil || !info.IsDir() {
154			return nil, report, recordError("the fixtures folder "+dir+" is not there", "check the folder", err)
155		}
156		fsys := os.DirFS(dir)
157		campaigns, err := recordCampaigns(dir, fsys, o.Campaigns)
158		if err != nil {
159			return nil, report, err
160		}
161		var jobs []recordJob
162		for _, campaign := range campaigns {
163			entries, err := fs.ReadDir(fsys, campaign)
164			if err != nil {
165				return nil, report, recordError("the campaign "+campaign+" cannot be read", "check the fixtures folder", err)
166			}
167			for _, e := range entries {
168				name, ok := strings.CutSuffix(e.Name(), ".http")
169				if e.IsDir() || !ok {
170					continue
171				}
172				if err := refuseLink(filepath.Join(dir, campaign, e.Name()), campaign+"/"+name); err != nil {
173					return nil, report, err
174				}
175				if o.Only != "" {
176					if match, _ := path.Match(o.Only, name); !match {
177						continue
178					}
179				}
180				job, skipped, err := planFixture(o, fsys, filepath.Join(dir, campaign, e.Name()), campaign, e.Name())
181				switch {
182				case err != nil:
183					return nil, report, err
184				case skipped != "":
185					report.Skipped = append(report.Skipped, campaign+"/"+name+": "+skipped)
186				default:
187					jobs = append(jobs, job)
188				}
189			}
190		}
191		return jobs, report, nil
192	}
193	
194	// refuseLink refuses a campaign folder or a fixture file that is a symbolic
195	// link: a link could carry a run, which sends the bench credentials and rewrites
196	// files, to something that is not in the fixtures folder. A path that cannot be
197	// inspected is left to the read that follows.
198	func refuseLink(filePath, label string) error {
199		if info, err := os.Lstat(filePath); err == nil && info.Mode()&os.ModeSymlink != 0 {
200			return recordError(label+" is a symbolic link", "replace the link with the real file or folder", nil)
201		}
202		return nil
203	}
204	
205	// recordCampaigns returns the campaigns to read: the ones asked for, each a plain
206	// folder name of fsys (dir on disk), or every folder of fsys. A campaign that is
207	// a symbolic link is refused, asked for or found.
208	func recordCampaigns(dir string, fsys fs.FS, wanted []string) ([]string, error) {
209		if len(wanted) == 0 {
210			entries, err := fs.ReadDir(fsys, ".")
211			if err != nil {
212				return nil, recordError("the fixtures folder cannot be read", "check the folder", err)
213			}
214			var all []string
215			for _, e := range entries {
216				if strings.HasPrefix(e.Name(), ".") {
217					continue
218				}
219				if e.Type()&fs.ModeSymlink != 0 {
220					return nil, recordError("the campaign "+e.Name()+" is a symbolic link", "replace the link with the real folder", nil)
221				}
222				if e.IsDir() {
223					all = append(all, e.Name())
224				}
225			}
226			return all, nil
227		}
228		for _, c := range wanted {
229			if c == "." || !fs.ValidPath(c) || strings.Contains(c, "/") {
230				return nil, recordError("the campaign "+strconv.Quote(c)+" is not a campaign name", "name a folder of the fixtures folder, with no path", nil)
231			}
232			if err := refuseLink(filepath.Join(dir, c), c); err != nil {
233				return nil, err
234			}
235			if info, err := fs.Stat(fsys, c); err != nil || !info.IsDir() {
236				return nil, recordError("the campaign "+c+" does not exist", "check the campaign name", err)
237			}
238		}
239		return wanted, nil
240	}
241	
242	// planFixture reads one fixture file. It returns the reason when the fixture is
243	// skipped, an error when it must not be sent.
244	func planFixture(o RecordOptions, fsys fs.FS, filePath, campaign, fileName string) (recordJob, string, error) {
245		label := campaign + "/" + strings.TrimSuffix(fileName, ".http")
246		data, err := fs.ReadFile(fsys, path.Join(campaign, fileName))
247		if err != nil {
248			return recordJob{}, "", recordError(label+" cannot be read", "check the file", err)
249		}
250		f, err := nexusfixture.Parse(campaign, fileName, data)
251		if err != nil {
252			return recordJob{}, "", recordError(label+" is not a valid fixture", "fix the file", err)
253		}
254		if reason, ok := strings.CutPrefix(f.Meta.Record, "skip"); ok {
255			return recordJob{}, strings.TrimSpace(strings.TrimPrefix(reason, ":")), nil
256		}
257		if len(f.Exchanges) != 1 {
258			return recordJob{}, fmt.Sprintf("holds %d exchanges, only one is recorded yet", len(f.Exchanges)), nil
259		}
260		// The file is scanned as it stands: a request header outside Host, the
261		// credentials and Accept, or a query other than n and last, refuses it.
262		if leaks := nexusfixture.CheckLeaks(label, data, recordTerms(o)); len(leaks) > 0 {
263			return recordJob{}, "", recordError(label+" is refused before it is sent: "+describeLeaks(leaks), "fix the file", nil)
264		}
265		ex := f.Exchanges[0]
266		if reason := refusedRequest(ex.Method, ex.Target); reason != "" {
267			return recordJob{}, "", recordError(label+" asks for something the recorder does not send ("+reason+")", "record only GET requests of the closed list of paths", nil)
268		}
269		origin, ok := o.Origins[ex.Host]
270		if !ok {
271			return recordJob{}, "", recordError(label+" is recorded on "+ex.Host+", which has no origin", "give the origin of this host:port", nil)
272		}
273		job := recordJob{campaign: campaign, name: label, path: filePath, current: f, origin: origin}
274		switch f.Identity {
275		case nexusfixture.Admin:
276			job.user, job.password = REDACTED, o.Secrets.AdminPassword
277		case nexusfixture.Pull:
278			job.user, job.password = REDACTED, o.Secrets.PullPassword
279		}
280		if job.user != "" && job.password == "" {
281			return recordJob{}, "", recordError("the bench has no stored password for "+job.user+", the account of "+label, upCheck, nil)
282		}
283		return job, "", nil
284	}
285	
286	// checkOrigins refuses an origin that is not a loopback URL, a key that is not a
287	// loopback host:port of the descriptor, and a run with no REST origin.
288	func checkOrigins(o RecordOptions) error {
289		known := descriptorOrigins(o.Descriptor)
290		for key, base := range o.Origins {
291			if !known[key] {
292				return recordError("the origin of "+key+" is not a loopback host:port of the bench descriptor", "give origins for the hosts and ports the descriptor lists", nil)
293			}
294			if err := requireLoopbackBase(base); err != nil {
295				return err
296			}
297		}
298		rest, ok := restOriginKey(o.Descriptor)
299		if _, have := o.Origins[rest]; !ok || !have {
300			return recordError("no origin is given for the REST port of the bench, which the data set check needs", "give the REST origin of the descriptor", nil)
301		}
302		return nil
303	}
304	
305	// descriptorOrigins is the set of loopback host:port pairs the descriptor
306	// publishes: every host of the descriptor on the REST and the Docker ports.
307	func descriptorOrigins(d Descriptor) map[string]bool {
308		ports := []int{d.REST.NodePort}
309		for _, c := range d.DockerConnectors {
310			ports = append(ports, c.NodePort)
311		}
312		known := map[string]bool{}
313		for _, h := range d.Hosts {
314			host := strings.Trim(h, "[]")
315			if !IsLoopbackRESTHost(host) {
316				continue
317			}
318			for _, p := range ports {
319				known[net.JoinHostPort(host, strconv.Itoa(p))] = true
320			}
321		}
322		return known
323	}
324	
325	// RecordOrigins builds RecordOptions.Origins from the descriptor: one entry per
326	// loopback host and port it publishes (the REST and the Docker ports), keyed
327	// host:port, valued with the http URL on restHost, which is the host of the key
328	// when empty.
329	func RecordOrigins(d Descriptor, restHost string) map[string]string {
330		origins := map[string]string{}
331		for key := range descriptorOrigins(d) {
332			host, portText, err := net.SplitHostPort(key)
333			port, convErr := strconv.Atoi(portText)
334			if err != nil || convErr != nil {
335				continue
336			}
337			if restHost != "" {
338				host = restHost
339			}
340			origins[key] = hostURL(host, port)
341		}
342		return origins
343	}
344	
345	// restOriginKey is the host:port of the REST API: the first host of the
346	// descriptor on the REST node port.
347	func restOriginKey(d Descriptor) (string, bool) {
348		if len(d.Hosts) == 0 || d.REST.NodePort == 0 {
349			return "", false
350		}
351		return net.JoinHostPort(strings.Trim(d.Hosts[0], "[]"), strconv.Itoa(d.REST.NodePort)), true
352	}
353	
354	// The closed list of what the recorder may ask for. A manifest or a blob read
355	// through a proxy repository would cache an image and change the bench, so none
356	// is allowed, whatever the path says.
357	var (
358		recordPaths = []*regexp.Regexp{
359			regexp.MustCompile(`^/v2/(_catalog|[a-z0-9._/-]+/tags/list)?$`),
360			regexp.MustCompile(`^/v2/[a-z0-9._-]+(/[a-z0-9._-]+)*/_catalog$`),
361			regexp.MustCompile(`^/repository/[A-Za-z0-9._-]+/v2/_catalog$`),
362			regexp.MustCompile(`^/service/rest/v1/repositories(/[A-Za-z0-9._-]+)*$`),
363		}
364		// recordQueryParam admits one percent escape only: %2F in the value of last,
365		// the form a Nexus group page Link gives the last name (DEVDESK-580).
366		recordQueryParam = regexp.MustCompile(`^(n=[0-9]{1,6}|last=([A-Za-z0-9._/-]|%2[Ff])*)$`)
367	)
368	
369	// refusedRequest returns why a request may not be sent, or "".
370	func refusedRequest(method, target string) string {
371		p, query, hasQuery := strings.Cut(target, "?")
372		switch {
373		case method != http.MethodGet:
374			return "the method is not GET"
375		case strings.Contains(target, "..") || strings.Contains(p, "%"):
376			// An escape in the query is left to recordQueryParam, which lets only %2F
377			// through in the value of last.
378			return "the target holds a dot-dot or an escape"
379		case strings.Contains(p+"/", "/manifests/") || strings.Contains(p+"/", "/blobs/"):
380			return "a manifest or a blob read can change the bench"
381		}
382		listed := false
383		for _, re := range recordPaths {
384			listed = listed || re.MatchString(p)
385		}
386		if !listed {
387			return "the path is not in the closed list"
388		}
389		if hasQuery {
390			for _, param := range strings.Split(query, "&") {
391				if !recordQueryParam.MatchString(param) {
392					return "the query holds more than n and last"
393				}
394			}
395		}
396		return ""
397	}
