399	// ---- the data set of the bench ---------------------------------------------------
400	
401	// checkBenchDataset compares, anonymously, what docker-hosted and docker-proxy
402	// list with the data set of the descriptor: a bench that does not hold it would
403	// record answers that are not the ones the fixtures describe. What cannot be read
404	// is a refusal too.
405	func checkBenchDataset(ctx context.Context, o RecordOptions) error {
406		if len(o.Descriptor.Dataset) == 0 {
407			return recordError("the descriptor lists no data set to compare the bench with", "run `mise run nexus-bench:seed`", nil)
408		}
409		key, _ := restOriginKey(o.Descriptor)
410		base := o.Origins[key]
411		for _, repo := range DatasetRepositories() {
412			listed, err := ListImagesAnonymously(ctx, base, repo)
413			if err != nil {
414				return recordError("the listing of "+repo+" could not be read, so the data set of the bench is unknown",
415					"check that the bench answers and that anonymous access is on", err)
416			}
417			diffs, ok := CompareDataset(DatasetIn(o.Descriptor.Dataset, repo), listed)
418			if !ok {
419				return recordError("the listing of "+repo+" gives no digest, so the data set of the bench cannot be compared", resetCheck, nil)
420			}
421			if diffs > 0 {
422				return recordError(fmt.Sprintf("%s differs from the data set of the descriptor (%d image(s))", repo, diffs), resetCheck, nil)
423			}
424		}
425		return nil
426	}
427	
428	// DatasetRepositories are the two repositories that hold the data set. The group
429	// is never read: a read through it can cache an image.
430	func DatasetRepositories() []string {
431		return []string{dockerHostedRepository, dockerProxyRepository}
432	}
433	
434	// DatasetIn returns the images of the data set that repo holds: the hosted ones
435	// in docker-hosted, the ones cached in the proxy in docker-proxy.
436	func DatasetIn(images []DescriptorImage, repo string) []DescriptorImage {
437		var out []DescriptorImage
438		for _, img := range images {
439			hosted := repo == dockerHostedRepository && img.Location == string(LocationHosted)
440			cached := repo == dockerProxyRepository && img.CachedInProxy
441			if hosted || cached {
442				out = append(out, img)
443			}
444		}
445		return out
446	}
447	
448	// CompareDataset counts the images of a repository that are missing, have
449	// another digest, or are not in the data set. ok is false when the listing gives
450	// no digest for an image that is there, which makes the comparison impossible.
451	func CompareDataset(want []DescriptorImage, listed []ListedImage) (diffs int, ok bool) {
452		have := make(map[string]string, len(listed))
453		for _, img := range listed {
454			have[img.Name+":"+img.Tag] = img.Digest
455		}
456		for _, img := range want {
457			key := img.Name + ":" + img.Tag
458			digest, found := have[key]
459			delete(have, key)
460			switch {
461			case !found:
462				diffs++
463			case digest == "":
464				return 0, false
465			case digest != img.Digest:
466				diffs++
467			}
468		}
469		return diffs + len(have), true
470	}
471	
472	// ---- gathering the answers ------------------------------------------------------
473	
474	// gatherAnswers asks every job and returns the files to write and the fixtures
475	// that did not change. The first problem ends the run: nothing is written yet.
476	func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged []string, err error) {
477		clients := map[string]*client{}
478		defer func() {
479			for _, c := range clients {
480				c.closeIdle()
481			}
482		}()
483		now := time.Now
484		if o.Now != nil {
485			now = o.Now
486		}
487		date := now().Format(recordedDateLayout)
488		for _, j := range jobs {
489			key := j.origin + "\x00" + j.user
490			c, ok := clients[key]
491			if !ok {
492				c = newClient(j.origin, j.user, j.password)
493				clients[key] = c
494			}
495			data, same, err := j.record(ctx, o, c, date)
496			switch {
497			case err != nil:
498				return nil, nil, err
499			case same:
500				unchanged = append(unchanged, j.name)
501			default:
502				writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
503			}
504		}
505		return writes, unchanged, nil
506	}
507	
508	// record asks the bench for the answer of the job and returns the bytes of the
509	// fixture it would write; same is true when the file already holds that answer.
510	func (j recordJob) record(ctx context.Context, o RecordOptions, c *client, date string) (data []byte, same bool, err error) {
511		ex := j.current.Exchanges[0]
512		status, header, body, err := c.exchange(ctx, ex.Method, ex.Target, ex.RequestHeader)
513		if err != nil {
514			return nil, false, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
515		}
516		if !benchVersionMatches(header.Get("Server"), o.Descriptor) {
517			return nil, false, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", upCheck, nil)
518		}
519		if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
520			return nil, false, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
521		}
522		answer := nexusfixture.Redact(nexusfixture.RawExchange{
523			Method: ex.Method, Target: ex.Target, Host: ex.Host, RequestHeader: ex.RequestHeader,
524			Status: status, Header: header, Body: body,
525		})
526		if answer.Stub == "" && answer.Header.Get("Content-Length") != "" {
527			// A redacted body is not as long as the one Nexus sent.
528			answer.Header.Set("Content-Length", strconv.Itoa(len(answer.Body)))
529		}
530		f := j.current
531		f.Meta.NexusVersion, f.Meta.Edition, f.Meta.NexusNote = o.Descriptor.NexusVersion, o.Descriptor.Edition, ""
532		f.Meta.Measured, f.Meta.RecordedBy = date, recordedBy
533		if f.Meta.Record == nexusfixture.RecordPending {
534			f.Meta.Record = ""
535		}
536		f.Exchanges = []nexusfixture.Exchange{answer}
537		data = nexusfixture.Format(f)
538	
539		// What will be written is read back and checked, not what was built.
540		back, err := nexusfixture.Parse(j.campaign, filepath.Base(j.path), data)
541		if err != nil || !bytes.Equal(nexusfixture.Format(back), data) {
542			return nil, false, recordError("the answer to "+j.name+" does not read back as a fixture", "do not record this answer", err)
543		}
544		if leaks := nexusfixture.CheckLeaks(j.name, data, recordTerms(o)); len(leaks) > 0 {
545			return nil, false, recordError("the answer to "+j.name+" would leak: "+describeLeaks(leaks), "nothing was written; fix the bench or the redaction", nil)
546		}
