611	// (a header outside the allowlist, an HTML body), for a term in the forms it can
612	// take: as is, in another case, URL-escaped, JSON-escaped.
613	func holdsTerm(header http.Header, body []byte, terms []string) bool {
614		var raw strings.Builder
615		for name, values := range header {
616			raw.WriteString(name + ": " + strings.Join(values, "\n") + "\n")
617		}
618		raw.Write(body)
619		text := strings.ToLower(raw.String())
620		jsonEscaper := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `/`, `\/`)
621		for _, term := range terms {
622			if term == "" {
623				continue
624			}
625			for _, v := range []string{term, url.QueryEscape(term), url.PathEscape(term), jsonEscaper.Replace(term)} {
626				if strings.Contains(text, strings.ToLower(v)) {
627					return true
628				}
629			}
630		}
631		return false
632	}
