338	// refuse runs the recorder and requires a refusal that names fixture (when not
339	// empty) and changes no file.
340	func (e *recEnv) refuse(fixture string) *BenchError {
341		e.t.Helper()
342		before := recSnapshot(e.t, e.dir)
343		rep, err := e.record()
344		be := requireRecordRefusal(e.t, err)
345		if fixture != "" && !strings.Contains(err.Error(), fixture) {
346			e.t.Errorf("the error %q does not name the fixture %q", err, fixture)
347		}
348		if len(rep.Written) != 0 {
349			e.t.Errorf("Written = %v after a refusal, want none", rep.Written)
350		}
351		requireSameFiles(e.t, before, recSnapshot(e.t, e.dir))
352		return be
353	}
