func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	// After the first signal cancels ctx, hand the signals back to the default
	// behavior so that a second Ctrl-C kills a run that is slow to wind down.
	context.AfterFunc(ctx, stop)
	code := run(ctx, os.Args[1:], os.Getenv, os.Stdout, os.Stderr, defaultDeps())
	stop()
	os.Exit(code)
}

// session is one subcommand being run: its context, its resolved parameters and
// its streams.
type session struct {
	ctx    context.Context
	p      nexusbench.Params
	getenv func(string) string
	stdout io.Writer
	stderr io.Writer
	d      deps
	// restHost is where the REST API is reached; explicit tells whether the
	// operator chose it.
	restHost string
	explicit bool
	// recordFlags are the flags only record takes.
	recordFlags recordFlags
}

// run executes one command line and returns the exit code: 0 for success, 1
// for a failure of the bench, 2 for a mistake in the command line.
func run(ctx context.Context, args []string, getenv func(string) string, stdout, stderr io.Writer, d deps) int {
	if len(args) == 0 {
		printUsage(stderr)
		return exitUsage
	}
	name := args[0]
	switch name {
	case "-h", "--help", "help":
		printUsage(stdout)
		return exitOK
	case "up", "provision", "down", "seed", "status", "render", "cut-upstream", "restore-upstream", "reset", "record":
	default:
		_, _ = fmt.Fprintf(stderr, "nexus-bench: unknown subcommand %q\n\n", name)
		printUsage(stderr)
		return exitUsage
	}

	flags := newFlagSet(name)
	if err := flags.parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printSubcommandHelp(stdout, name, flags)
			return exitOK
		}
		_, _ = fmt.Fprintf(stderr, "nexus-bench %s: %v\nRun nexus-bench %s -h for the flags.\n", name, err, name)
		return exitUsage
	}

	s := &session{ctx: ctx, getenv: getenv, stdout: stdout, stderr: stderr, d: d, restHost: loopbackHost, recordFlags: flags.record}
	p, err := flags.resolveParams(getenv)
	if err != nil {
		return s.fail(err)
	}
	s.p = p

package nexusbench

import (
	"context"
	"encoding/json"
	"fmt"
	"slices"
	"strings"
)

// Op is what a run of the bench is about to do; it decides which checks the
// preflight makes.
type Op int

const (
	OpUp Op = iota
	OpProvision
	OpDown
	OpStatus
	// OpSeed is appended after OpStatus: no earlier value moves.
	OpSeed
	// OpCut, OpRestore and OpReset follow OpSeed, in this order.
	OpCut
	OpRestore
	OpReset
)

// readsNode is true for the operations that return the node address: down and
// the ones that go through the loopback (seed, cut, restore, reset) do not.
func (op Op) readsNode() bool {
	return op == OpUp || op == OpProvision || op == OpStatus
}

// PreflightResult is what a successful preflight learned about the cluster.
type PreflightResult struct {
	// NamespaceExists is true when the bench namespace is there.
	NamespaceExists bool
	// NamespaceOurs is true when it carries our managed-by label.
	NamespaceOurs bool
	// NodeIP is the InternalIP of the first node that reports one; empty when
	// none does, which is not an error (the other hosts still work). It is not
	// read for OpDown.
	NodeIP string
}

const (
	// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
	// puts on the namespace; down deletes a namespace only when it carries it.
	managedByLabel = "app.kubernetes.io/managed-by"
	managedByValue = "devdesk-nexus-bench"

	// nexusServiceName is the Service 30-service.yaml.tmpl creates.
	nexusServiceName = "nexus"

	// requestTimeout bounds every call that reaches the API server.
	requestTimeout = "--request-timeout=10s"
)

// permissionScope says where a can-i question applies.
type permissionScope int

const (
	scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
	scopeNamespace                        // -n <namespace>
	scopeAll                              // -A
)

// permission is one "kubectl auth can-i" question the preflight asks.
type permission struct {
	verb, resource string
	// subresource is asked as --subresource=<sub>: kubectl reads "pods/exec" as
	// the object "exec" of the pods, not as the exec subresource.
	subresource string
	scope       permissionScope
}

// name is the resource as a message shows it: "pods/exec".
func (perm permission) name() string {
	if perm.subresource == "" {
		return perm.resource
	}
	return perm.resource + "/" + perm.subresource
}

// seedPermissions are the questions of seed, which restore asks too and reset
// asks first. Seed reads the Deployment and the pods of the upstream, scales it
// back when it is cut, and reaches it through a port-forward, which gets the
// Service, then the pod it picks, before it opens the tunnel. EnsureUpstream
// reads the claim on every turn of its wait, so the two claim questions come
// before the first write.
var seedPermissions = []permission{
	{"get", "deployments", "", scopeNamespace},
	{"list", "pods", "", scopeNamespace},
	{"get", "pods", "", scopeNamespace},
	{"get", "services", "", scopeNamespace},
	{"get", "persistentvolumeclaims", "", scopeNamespace},
	{"list", "persistentvolumeclaims", "", scopeNamespace},
	{"create", "pods", "portforward", scopeNamespace},
	{"patch", "deployments", "scale", scopeNamespace},
}

// permissionsByOp is the list F2 of the plan: what each operation needs. An
// operation absent from the map (status) writes nothing and asks nothing.
var permissionsByOp = map[Op][]permission{
	OpUp: {
		{"create", "namespaces", "", scopeCluster},
		{"create", "persistentvolumeclaims", "", scopeNamespace},
		{"create", "services", "", scopeNamespace},
		{"create", "deployments", "", scopeNamespace},
		{"create", "pods", "exec", scopeNamespace},
		{"list", "services", "", scopeAll},
		// Server-side apply is a PATCH, also on a second run (the namespace
		// included), and Deploy reads the pods and the claims of the namespace
		// while it waits.
		{"patch", "namespaces", "", scopeCluster},
		{"patch", "deployments", "", scopeNamespace},
		{"patch", "services", "", scopeNamespace},
		{"patch", "persistentvolumeclaims", "", scopeNamespace},
		{"get", "pods", "", scopeNamespace},
		{"list", "pods", "", scopeNamespace},
		{"get", "persistentvolumeclaims", "", scopeNamespace},
		{"list", "persistentvolumeclaims", "", scopeNamespace},
		// The upstream: EnsureUpstream scales it, and the seed that follows up
		// reaches it through a port-forward, which reads the Service first. Asked
		// last, so the fourteen above stay where they were.
		{"patch", "deployments", "scale", scopeNamespace},
		{"create", "pods", "portforward", scopeNamespace},
		{"get", "services", "", scopeNamespace},
	},
	// Provision waits for the Deployment and reads the pods before it execs.
	OpProvision: {
		{"create", "pods", "exec", scopeNamespace},
		{"get", "deployments", "", scopeNamespace},
		{"list", "pods", "", scopeNamespace},
	},
	OpDown:    {{"delete", "namespaces", "", scopeCluster}},
	OpSeed:    seedPermissions,
	OpRestore: seedPermissions,
	// Cut reads the upstream Deployment, waits until no pod is left and scales
	// it to zero: no tunnel, no Service, no claim.
	OpCut: {
		{"get", "deployments", "", scopeNamespace},
		{"list", "pods", "", scopeNamespace},
		{"patch", "deployments", "scale", scopeNamespace},
	},
	// Reset recycles the claim: what restore asks, then the writes on the claim
	// (a server-side apply of an absent claim needs create). It never execs: the
	// admin password is not changed.
	OpReset: slices.Concat(seedPermissions, []permission{
		{"delete", "persistentvolumeclaims", "", scopeNamespace},
		{"create", "persistentvolumeclaims", "", scopeNamespace},
		{"patch", "persistentvolumeclaims", "", scopeNamespace},
	}),
}

// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
// returns what it learned. Nothing is written to the cluster, whatever the
// outcome: a failure here means no write was ever issued. The checks run in a
// fixed order and stop at the first failure, so nothing is asked of a cluster
// the context does not reach:
package nexusbench

import (
	"context"
	"fmt"
	"io"
	"slices"
	"strings"
	"time"
)

// upstreamPollInterval separates two rounds of the wait for the upstream. It is
// shorter than pollInterval: a registry is ready within seconds of its image
// being local, and the wait has no host to probe.
const upstreamPollInterval = 2 * time.Second

// UpstreamState is what the cluster says about the bench upstream registry.
type UpstreamState int

// The states of the upstream, from the least to the most alive.
const (
	// UpstreamMissing: the Deployment bench-upstream does not exist.
	UpstreamMissing UpstreamState = iota
	// UpstreamCut: the Deployment exists with zero replicas.
	UpstreamCut
	// UpstreamStarting: one replica is wanted and no pod of it is ready yet.
	UpstreamStarting
	// UpstreamReady: a pod of the upstream that is not terminating is ready.
	UpstreamReady
)

// ReadUpstream reads the state of the bench upstream with read-only kubectl
// calls: it writes nothing and waits for nothing. A pod that fails to pull is
// Starting, not an error: diagnosing is the job of the wait. It runs no
// preflight; the caller does. Every failure is a *BenchError, but a cancelled
// context, which is returned as is.
func ReadUpstream(ctx context.Context, r Runner, p Params) (UpstreamState, error) {
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", out: io.Discard}
	return d.readUpstream(ctx)
}

// EnsureUpstream brings the bench upstream to one ready replica, and returns
// when it is ready or fails with a diagnosis. It reads first and writes only
// when the upstream is cut: one scale to one replica, then the wait. A starting
// upstream is waited for without a write; a ready one is left alone. The
// Deployment itself is applied by Deploy, so a missing one is an error. A
// custom upstream (Params.UpstreamIsBench is false) is refused before any call:
// the bench scales what it deploys and nothing else. The wait polls the pods
// and the claim of the upstream only, until Params.Timeout. It runs no
// preflight; the caller does. Every failure is a *BenchError, but a cancelled
// context, which is returned as is. A nil out discards the progress lines.
func EnsureUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	// The runner of a test may ignore ctx; the first call must not depend on it.
	if err := ctx.Err(); err != nil {
		return err
	}
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
	state, err := d.readUpstream(ctx)
	if err != nil {
		return err
	}
	switch state {
	case UpstreamMissing:
		return missingUpstreamError(d)
	case UpstreamReady:
		d.say("the upstream is ready")
		return nil
	case UpstreamCut:
		d.say("scaling the upstream to one replica")
		if err := d.scaleUpstream(ctx, 1); err != nil {
			return err
		}
	case UpstreamStarting:
		d.say("the upstream is starting")
	}
	return d.waitUpstream(ctx)
}

// missingUpstreamError is the error of an upstream that Deploy never applied.
func missingUpstreamError(d *deployer) *BenchError {
	p := d.pf.p
	return &BenchError{
		Kind:  Unclassified,
		Cause: fmt.Sprintf("the Deployment %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
		Check: "run `mise run nexus-bench:up`, which applies it, or " + d.pf.command("get", "deployment", upstreamDeployment, "-n", p.Namespace),
	}
}

