// descriptor of a provisioned bench (like seed), the others need nothing. It
// returns the bytes of the descriptor, nil when there is none.
func (h *harness) prepare(sub string) []byte {
	h.t.Helper()
	if sub == "reset" {
		return h.writePreviousDescriptor()
	}
	return nil
}

