func TestRecordRefusesANegativeRequestTimeoutBeforeRecording(t *testing.T) {
	r := newRecordRig(t)
	code, stdout, stderr := r.run("--request-timeout", "-5s")
	if code == 0 {
		t.Errorf("exit code = 0, want a refusal\nstdout: %s", stdout)
